CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS kontrol;
CREATE TABLE IF NOT EXISTS kontrol.tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS kontrol.objects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES kontrol.tenants(id), kind text NOT NULL, external_key text, payload jsonb NOT NULL, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, kind, external_key, valid_from));
CREATE TABLE IF NOT EXISTS kontrol.edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES kontrol.tenants(id), source_id uuid NOT NULL, relation text NOT NULL, target_id uuid NOT NULL, confidence numeric(4,3) NOT NULL CHECK (confidence BETWEEN 0 AND 1), rationale text NOT NULL, source_ref text, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz);
CREATE TABLE IF NOT EXISTS kontrol.evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES kontrol.tenants(id), control_id uuid, asset_id uuid, object_uri text, content_hash text NOT NULL, metadata jsonb NOT NULL, collected_at timestamptz NOT NULL, expires_at timestamptz, status text NOT NULL);
CREATE TABLE IF NOT EXISTS kontrol.audit_log (sequence bigint GENERATED ALWAYS AS IDENTITY, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES kontrol.tenants(id), actor_id text NOT NULL, action text NOT NULL, object_type text NOT NULL, object_id text NOT NULL, payload jsonb NOT NULL, previous_hash text, entry_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS objects_tenant_kind ON kontrol.objects(tenant_id, kind) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS edges_source ON kontrol.edges(tenant_id, source_id, relation) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS evidence_control ON kontrol.evidence(tenant_id, control_id, collected_at DESC);
CREATE INDEX IF NOT EXISTS audit_tenant_sequence ON kontrol.audit_log(tenant_id, sequence);
ALTER TABLE kontrol.objects ENABLE ROW LEVEL SECURITY;
ALTER TABLE kontrol.edges ENABLE ROW LEVEL SECURITY;
ALTER TABLE kontrol.evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE kontrol.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_objects ON kontrol.objects USING (tenant_id::text = current_setting('app.tenant_id', true));
CREATE POLICY tenant_edges ON kontrol.edges USING (tenant_id::text = current_setting('app.tenant_id', true));
CREATE POLICY tenant_evidence ON kontrol.evidence USING (tenant_id::text = current_setting('app.tenant_id', true));
CREATE POLICY tenant_audit ON kontrol.audit_log USING (tenant_id::text = current_setting('app.tenant_id', true));
